sys_script_include.script:
var CampusFoodLogin = Class.create();

CampusFoodLogin.prototype = {

    validateLogin: function(username, password) {

        var result = {
            success: false,
            message: '',
            userId: '',
            userName: '',
            role: '',
            dashboard: ''
        };


        // ==========================================
        // CHECK USER
        // ==========================================

        if (!username || !password) {

            result.message =
                'Username and password are required.';

            return result;
        }


        var userGR = new GlideRecord('sys_user');

        userGR.addQuery('user_name', username);
        userGR.addActiveQuery();
        userGR.query();


        if (!userGR.next()) {

            result.message =
                'Invalid username or password.';

            return result;
        }


        result.userId =
            userGR.getUniqueValue();

        result.userName =
            userGR.getDisplayValue('name');


        // ==========================================
        // CHECK USER'S GROUPS
        // ==========================================

        var memberGR =
            new GlideRecord('sys_user_grmember');

        memberGR.addQuery(
            'user',
            userGR.getUniqueValue()
        );

        memberGR.query();


        while (memberGR.next()) {

            var groupID =
                memberGR.getValue('group');


            // ==========================================
            // CHECK ADMIN ROLE
            // ==========================================

            var groupRoleGR =
                new GlideRecord('sys_group_has_role');

            groupRoleGR.addQuery(
                'group',
                groupID
            );

            groupRoleGR.addQuery(
                'role.name',
                'x_snc_campus_foo_1.admin'
            );

            groupRoleGR.query();


            if (groupRoleGR.next()) {

                result.success = true;
                result.role = 'ADMIN';

                result.dashboard =
                    '/food_services?id=food_service_admin_dashboard_page';

                return result;
            }


            // ==========================================
            // CHECK MANAGER ROLE
            // ==========================================

            groupRoleGR =
                new GlideRecord('sys_group_has_role');

            groupRoleGR.addQuery(
                'group',
                groupID
            );

            groupRoleGR.addQuery(
                'role.name',
                'x_snc_campus_foo_1.manager'
            );

            groupRoleGR.query();


            if (groupRoleGR.next()) {

                result.success = true;
                result.role = 'MANAGER';

                result.dashboard =
                    '/food_services?id=food_service_manager_dashboard_page';

                return result;
            }


            // ==========================================
            // CHECK STAFF ROLE
            // ==========================================

            groupRoleGR =
                new GlideRecord('sys_group_has_role');

            groupRoleGR.addQuery(
                'group',
                groupID
            );

            groupRoleGR.addQuery(
                'role.name',
                'x_snc_campus_foo_1.staff'
            );

            groupRoleGR.query();


            if (groupRoleGR.next()) {

                result.success = true;
                result.role = 'STAFF';

                result.dashboard =
                    '/food_services?id=food_services_staff_dashboard_page';

                return result;
            }


            // ==========================================
            // CHECK STUDENT ROLE
            // ==========================================

            groupRoleGR =
                new GlideRecord('sys_group_has_role');

            groupRoleGR.addQuery(
                'group',
                groupID
            );

            groupRoleGR.addQuery(
                'role.name',
                'x_snc_campus_foo_1.student'
            );

            groupRoleGR.query();


            if (groupRoleGR.next()) {

                result.success = true;
                result.role = 'STUDENT';

                result.dashboard =
                    '/food_services?id=food_service_student_dashbaord';

                return result;
            }
        }


        // ==========================================
        // NO CAMPUSFOOD ROLE FOUND
        // ==========================================

        result.message =
            'User found, but no CampusFood role was found.';

        return result;
    },


    type: 'CampusFoodLogin'
};
